import{_ as a,c as d,o as e,b0 as s}from"./chunks/framework.C5ev1SXp.js";const n="/scm-docs/assets/task-state.C20q52VP.svg",b=JSON.parse('{"title":"LV010-任务的状态与调度","description":null,"frontmatter":{"title":"LV010-任务的状态与调度","date":"2026-11-18T18:40:37.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/advanced-chapter/rtos/rtos-task/126d68c08a6509dce1ba46e4","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-11-18T18:40:37.157Z","fulluuid":"ce1ba46e49744aea9a608bf55f7fd4e2","useduuid":"ce1ba46e4"}},"headers":[],"relativePath":"sdoc/advanced-chapter/rtos/rtos-task/126d68c08a6509dce1ba46e4.md","filePath":"sdoc/30-进阶篇/90-FreeRTOS/02-任务管理/LV010-任务的状态与调度.md","lastUpdated":1795000891000}'),r={name:"sdoc/advanced-chapter/rtos/rtos-task/126d68c08a6509dce1ba46e4.md"};function o(i,t,l,c,p,h){return e(),d("div",null,[...t[0]||(t[0]=[s('<h1 id="lv010-任务的状态与调度" tabindex="-1">LV010-任务的状态与调度 <a class="header-anchor" href="#lv010-任务的状态与调度" aria-label="Permalink to &quot;LV010-任务的状态与调度&quot;">​</a></h1><h2 id="一、-四种状态" tabindex="-1">一、 四种状态 <a class="header-anchor" href="#一、-四种状态" aria-label="Permalink to &quot;一、 四种状态&quot;">​</a></h2><p><img src="'+n+`" alt="任务的四种状态与迁移"></p><table tabindex="0"><thead><tr><th>状态</th><th>含义</th><th>挂在哪条链表</th><th>怎么进入</th></tr></thead><tbody><tr><td>就绪 Ready</td><td>条件已具备，只差 CPU</td><td><code>pxReadyTasksLists[优先级]</code></td><td>创建成功、被抢占、事件唤醒</td></tr><tr><td>运行 Running</td><td>正占用 CPU，由 <code>pxCurrentTCB</code> 指向</td><td>同上（表头）</td><td>被调度器选中</td></tr><tr><td>阻塞 Blocked</td><td>在等事件或超时</td><td>延时链表 + 事件链表</td><td><code>osDelay</code>、等队列/信号量</td></tr><tr><td>挂起 Suspended</td><td>被外力停下，与时间无关</td><td>挂起链表</td><td><code>osThreadSuspend()</code></td></tr><tr><td>已删除 Deleted</td><td>生命周期终点</td><td>全部摘除</td><td><code>vTaskDelete()</code></td></tr></tbody></table><p>三个容易混淆的点：</p><ul><li><p>就绪与运行只差&quot;是否占着 CPU&quot;；<strong>同一优先级可以有多个就绪任务</strong>，按时间片轮转，而运行态单核只有一个</p></li><li><p>阻塞是任务<strong>主动</strong>的选择，挂起是<strong>别人</strong>强加的。挂起期间即使等到的事件已经到达，也不会转成就绪，必须再被 <code>osThreadResume()</code></p></li><li><p><strong>&quot;已删除&quot;严格说不是状态</strong>：<code>vTaskDelete()</code> 后 TCB 从所有链表摘除，内存交给空闲任务回收</p></li></ul><p>阻塞的三种典型写法：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">osDelay</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                  /* 等节拍 */</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">osMessageQueueGet</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(q, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">msg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         /* 等队列，最多 100 tick */</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">osSemaphoreAcquire</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(sem, osWaitForever);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        /* 无限等待 */</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>注意最后一个参数：<code>0</code> 表示&quot;不等待，立即返回&quot;，无限等待要写 <code>osWaitForever</code>。这是 CMSIS-RTOS2 里最常见的误用之一。</p><h2 id="二、-迁移的触发条件" tabindex="-1">二、 迁移的触发条件 <a class="header-anchor" href="#二、-迁移的触发条件" aria-label="Permalink to &quot;二、 迁移的触发条件&quot;">​</a></h2><h3 id="_1-完整迁移表" tabindex="-1">1. 完整迁移表 <a class="header-anchor" href="#_1-完整迁移表" aria-label="Permalink to &quot;1. 完整迁移表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>源状态</th><th>触发</th><th>目标状态</th><th>触发者</th></tr></thead><tbody><tr><td>创建</td><td><code>osThreadNew</code> 成功</td><td>就绪</td><td>创建者</td></tr><tr><td>就绪</td><td>被调度器选中</td><td>运行</td><td>内核</td></tr><tr><td>运行</td><td><code>osDelay</code> / 等事件</td><td>阻塞</td><td>任务自己</td></tr><tr><td>运行</td><td>更高优先级就绪</td><td>就绪</td><td>中断或内核</td></tr><tr><td>运行</td><td>同优先级时间片用尽</td><td>就绪</td><td>节拍中断</td></tr><tr><td>运行</td><td><code>osThreadSuspend</code></td><td>挂起</td><td>其它任务/中断</td></tr><tr><td>运行</td><td><code>vTaskDelete</code></td><td>删除</td><td>自己或别人</td></tr><tr><td>阻塞</td><td>事件到达</td><td>就绪</td><td>中断或内核</td></tr><tr><td>阻塞</td><td>超时</td><td>就绪</td><td>节拍中断</td></tr><tr><td>阻塞</td><td><code>osThreadSuspend</code></td><td>挂起</td><td>其它任务</td></tr><tr><td>挂起</td><td><code>osThreadResume</code></td><td>就绪</td><td>其它任务</td></tr><tr><td>挂起</td><td><code>vTaskDelete</code></td><td>删除</td><td>其它任务</td></tr></tbody></table><h3 id="_2-四类触发方式" tabindex="-1">2. 四类触发方式 <a class="header-anchor" href="#_2-四类触发方式" aria-label="Permalink to &quot;2. 四类触发方式&quot;">​</a></h3><ul><li><p><strong>主动让出</strong>：<code>osDelay()</code> 把任务挂到延时链表并立即触发一次调度；<code>osDelay(0)</code> 不阻塞，只把 CPU 让给同优先级的下一个任务</p></li><li><p><strong>被动抢占</strong>：高优先级任务因中断被唤醒时，内核在中断退出前挂起 <code>PendSV</code>，异常返回那一刻完成切换，被打断的任务回到就绪</p></li><li><p><strong>事件唤醒</strong>：被唤醒<strong>不会直接运行</strong>，要先回到就绪再被选中（<code>阻塞 → 就绪 → 运行</code>）；此刻若有更高优先级任务在跑，唤醒者继续排队</p></li><li><p><strong>挂起与恢复</strong>：挂起是外力，与超时无关；挂起期间即使等的信号量已经到达也不会转就绪——唤醒与恢复是两个独立条件，必须同时满足</p></li></ul><h2 id="三、-调度时机" tabindex="-1">三、 调度时机 <a class="header-anchor" href="#三、-调度时机" aria-label="Permalink to &quot;三、 调度时机&quot;">​</a></h2><h3 id="_1-三个切换入口" tabindex="-1">1. 三个切换入口 <a class="header-anchor" href="#_1-三个切换入口" aria-label="Permalink to &quot;1. 三个切换入口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>入口</th><th>何时</th><th>结果</th></tr></thead><tbody><tr><td><code>xTaskIncrementTick</code></td><td>每 1 ms 节拍</td><td>延时到期、时间片轮转</td></tr><tr><td>中断退出</td><td>中断里唤醒了更高优先级任务</td><td>立即抢占</td></tr><tr><td>显式调用</td><td><code>taskYIELD()</code>、<code>osDelay(0)</code></td><td>主动让出</td></tr></tbody></table><p>三者最终都汇聚到 <code>PendSV</code> 完成真正的现场切换。</p><h3 id="_2-pendsv-为什么用最低优先级" tabindex="-1">2. PendSV 为什么用最低优先级 <a class="header-anchor" href="#_2-pendsv-为什么用最低优先级" aria-label="Permalink to &quot;2. PendSV 为什么用最低优先级&quot;">​</a></h3><p>PendSV 被设为最低优先级（15），作用是<strong>把切换推迟到所有中断处理完之后</strong>再执行。否则如果在某个中断里刚唤醒高优先级任务就立即切换，会打断尚未处理完的其它中断。</p><p>这也解释了为什么切换看起来&quot;瞬时&quot;：中断一退出，PendSV 立刻接上。</p><h3 id="_3-上下文切换的开销" tabindex="-1">3. 上下文切换的开销 <a class="header-anchor" href="#_3-上下文切换的开销" aria-label="Permalink to &quot;3. 上下文切换的开销&quot;">​</a></h3><table tabindex="0"><thead><tr><th>步骤</th><th>内容</th><th>约耗时（72 MHz）</th></tr></thead><tbody><tr><td>硬件压栈</td><td>8 个字（<code>R0-R3</code>、<code>R12</code>、<code>LR</code>、<code>PC</code>、<code>xPSR</code>）</td><td>12 周期</td></tr><tr><td>软件保存</td><td>8 个字（<code>R4-R11</code>）</td><td>10 周期</td></tr><tr><td>选下一个任务</td><td>扫描就绪链表</td><td>数十周期</td></tr><tr><td>恢复现场</td><td>反向操作</td><td>20 周期</td></tr></tbody></table><p>合计约 1~2 µs。对 1 ms 的节拍来说，占比 0.1%~0.2%。</p><h2 id="四、-调度策略" tabindex="-1">四、 调度策略 <a class="header-anchor" href="#四、-调度策略" aria-label="Permalink to &quot;四、 调度策略&quot;">​</a></h2><h3 id="_1-优先级与时间片" tabindex="-1">1. 优先级与时间片 <a class="header-anchor" href="#_1-优先级与时间片" aria-label="Permalink to &quot;1. 优先级与时间片&quot;">​</a></h3><p><code>configUSE_PREEMPTION = 1</code>，只要有更高优先级任务就绪，立即切换。本工程优先级：</p><table tabindex="0"><thead><tr><th>优先级</th><th>任务</th><th>说明</th></tr></thead><tbody><tr><td>25</td><td>defaultTask</td><td>最高，LED 与命令执行</td></tr><tr><td>9</td><td>shellTask</td><td>串口交互</td></tr><tr><td>8</td><td>heartbeatTask</td><td>后台日志</td></tr><tr><td>2</td><td>Tmr Svc</td><td>软件定时器</td></tr><tr><td>0</td><td>IDLE</td><td>空闲</td></tr></tbody></table><p>同优先级之间才谈时间片：<code>configUSE_TIME_SLICING</code> 未定义，默认 1，时间片 = 1 个 tick（1 ms）。本工程五个任务优先级全不同，所以<strong>轮转从未发生</strong>，是纯抢占式调度。</p><h3 id="_2-空闲任务" tabindex="-1">2. 空闲任务 <a class="header-anchor" href="#_2-空闲任务" aria-label="Permalink to &quot;2. 空闲任务&quot;">​</a></h3><p>IDLE 优先级 0，保证&quot;任何时候都有任务可跑&quot;。它承担三件事：</p><ul><li>回收已删除任务的栈与 TCB（<code>prvIdleTask</code> 里的清理循环）</li><li>调用 <code>vApplicationIdleHook()</code>（若开启）</li><li>让 CPU 空转，统计上表现为&quot;空闲占比&quot;</li></ul><h3 id="_3-优先级反转与继承" tabindex="-1">3. 优先级反转与继承 <a class="header-anchor" href="#_3-优先级反转与继承" aria-label="Permalink to &quot;3. 优先级反转与继承&quot;">​</a></h3><p>高优先级任务等一把被低优先级任务持有的锁，而中优先级任务抢走了 CPU——就是优先级反转。FreeRTOS 的互斥量支持继承：持锁者临时升到等待者的优先级，释放后恢复 <code>uxBasePriority</code>。</p><p>注意只有<strong>互斥量</strong>支持继承，二值信号量不支持。</p><h2 id="五、-观察与实测" tabindex="-1">五、 观察与实测 <a class="header-anchor" href="#五、-观察与实测" aria-label="Permalink to &quot;五、 观察与实测&quot;">​</a></h2><h3 id="_1-ps-的状态列" tabindex="-1">1. ps 的状态列 <a class="header-anchor" href="#_1-ps-的状态列" aria-label="Permalink to &quot;1. ps 的状态列&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>atk-f103# ps</span></span>
<span class="line"><span>  NAME             STATE  PRIO     FREE</span></span>
<span class="line"><span>  shellTask        RUN       9     1008</span></span>
<span class="line"><span>  IDLE             READY     0      440</span></span>
<span class="line"><span>  heartbeatTask    BLOCK     8      728</span></span>
<span class="line"><span>  defaultTask      BLOCK    25      864</span></span>
<span class="line"><span>  Tmr Svc          BLOCK     2      920</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><code>RUN</code> 是执行 <code>ps</code> 的那个任务，<code>READY</code> 表示就绪但没轮到，<code>BLOCK</code> 表示在等事件。<strong>没有 <code>SUSP</code></strong>，说明本工程没有挂起任何任务。</p><h3 id="_2-top-的-cpu-占比" tabindex="-1">2. top 的 CPU 占比 <a class="header-anchor" href="#_2-top-的-cpu-占比" aria-label="Permalink to &quot;2. top 的 CPU 占比&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  NAME                RUN(ms)   CPU</span></span>
<span class="line"><span>  IDLE                   4170   99%</span></span>
<span class="line"><span>  shellTask                 2    0%</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>IDLE</code> 高说明负载轻；若某业务任务接近 100%，就要查它是不是在忙等。</p><h3 id="_3-三个现象的解释" tabindex="-1">3. 三个现象的解释 <a class="header-anchor" href="#_3-三个现象的解释" aria-label="Permalink to &quot;3. 三个现象的解释&quot;">​</a></h3><p><strong>心跳为什么不漂移</strong>：<code>heartbeatTask</code> 用的是 <code>osDelayUntil(tick += 5000)</code>，基准是绝对节拍，打印耗时不参与累加。实测 <code>count=40</code> 对应 <code>uptime=200 s</code>，严格 5 秒一次。</p><p><strong>burn 为什么能吃满</strong>：<code>burn</code> 任务在循环里从不调用阻塞 API，只要它的优先级高于其它就绪任务，就一直占着 CPU，直到自己删除。</p><p><strong>删除任务后占比之和为什么小于 100%</strong>：TCB 被回收后，<code>uxTaskGetSystemState()</code> 再也读不到它的累计时间，缺口就是已删除任务消耗的部分。</p><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>`,48)])])}const k=a(r,[["render",o]]);export{b as __pageData,k as default};
